AgentWebView::AgentWebView(wxWindow*                                  parent,
                           const ShellTheme&                          theme,
                           Workspace::IWorkspace&                     workspace,
                           Agent::ProjectPersistence*                 borrowed,
                           std::unique_ptr<Agent::ProjectPersistence> own_document,
                           Agent::AgentAvailability                   availability,
                           Agent::AgentServicePtr                     agent,
                           Agent::AgentSetupServicePtr                setup,
                           AgentPageMode                              mode)
    : wxPanel(parent, wxID_ANY)
    , m_theme(theme)
    , m_own_document(std::move(own_document))
    , m_host(std::make_unique<Agent::AgentHost>(workspace, borrowed != nullptr ? *borrowed : *m_own_document, availability, GUI_App::dark_mode(),
                                                std::move(agent), std::move(setup)))
    , m_handshake_timer(this, kHandshakeTimerId)
{
    m_host->set_page_error_handler([](const std::string& error, const std::string& where, const std::string& event) {
        report_unexpected_error("running the app page's code", error, where, event);
    });
    m_host->set_step_listener([](const char* category, const std::string& step) { sentry_breadcrumb(category, step); });
    m_host->set_unexpected_error_handler([](const std::string& doing, std::exception_ptr error) {
        try {
            std::rethrow_exception(error);
        } catch (const Agent::ToolCallFailure&) {
            report_if_automatic(doing, describe_current_exception());
        } catch (...) {
            report_unexpected_error(doing, describe_current_exception());
        }
    });
    m_host->set_chat_titles_file((boost::filesystem::path(data_dir()) / "jusprin" / "chat-titles.json").string());
    m_host->set_mcp_cli_runner([this](const std::vector<std::string>& arguments, Agent::AgentHost::McpCliDone done) {
        start_mcp_setup_command(this, arguments, [complete = std::move(done)](McpSetupResult result) {
            complete(result.success, std::move(result.diagnostic));
        });
    });
    // The host resolves which file this is; it only lacks a way to show it.
    // Deferred rather than called inline: this runs inside the web view's
    // script-message handler, and handing the file manager the main thread
    // before that handler returns is a way to stall the view's own message
    // pump. Nothing here depends on the reveal having happened.
    m_host->set_reveal_path_handler([this](const std::string& path) {
    if (reported || wxGetApp().app_config == nullptr)
        return;
    reported = true;

    AppConfig& config = *wxGetApp().app_config;
    // The same stealth mode the update check reads: the person asked the app
    // to make no calls of its own.
    if (config.get_bool("stealth_mode"))
        return;

    const std::string body = launch_report_body(install_id(config), version_label(), std::string(wxGetOsDescription().ToUTF8()));
    Http::post(Agent::cloud_launches_url(&config))
        .header("Content-Type", "application/json")
        .header("User-Agent", user_agent())
        .set_post_body(body)
        .timeout_connect(5)
        .timeout_max(10)
        .on_error([](std::string answer, std::string error, unsigned status) {
            // On the HTTP thread; report_if_automatic goes on to the main thread.
            if (const auto report = launch_failure_report(status, answer))
                report_if_automatic("telling JusPrin's server that the app started", *report);
            else
                BOOST_LOG_TRIVIAL(info) << "JusPrin's start report reached no server: " << error;
        })
        .perform();
}

} // namespace Slic3r::GUI::JusPrin::Updates
